        "log_send" to mapOf("ms" to "Pošli zapis", "en" to "Send the log", "pl" to "Wyślij zapis", "nb" to "Send loggen", "cs" to "Odeslat záznam", "sk" to "Odoslať záznam", "sl" to "Pošlji dnevnik", "hr" to "Pošalji zapis", "sr" to "Pošalji zapis", "bs" to "Pošalji zapis", "mk" to "Испрати го записот", "ru" to "Отправить журнал", "uk" to "Надіслати журнал", "bg" to "Изпрати дневника", "be" to "Адправіць журнал", "sr-Cyrl" to "Пошаљи запис"),
        "log_subject" to mapOf("ms" to "Zapis gestov", "en" to "Gesture log", "pl" to "Zapis gestów", "nb" to "Sveipelogg", "cs" to "Záznam gest", "sk" to "Záznam giest", "sl" to "Dnevnik potez", "hr" to "Zapis gesta", "sr" to "Zapis pokreta", "bs" to "Zapis pokreta", "mk" to "Запис на гестови", "ru" to "Журнал жестов", "uk" to "Журнал жестів", "bg" to "Дневник на жестовете", "be" to "Журнал жэстаў", "sr-Cyrl" to "Запис покрета"),
        "log_toggle" to mapOf("ms" to "Zapisyvati gesty", "en" to "Record gestures", "pl" to "Zapisuj gesty", "nb" to "Lagre sveip", "cs" to "Zaznamenávat gesta", "sk" to "Zaznamenávať gestá", "sl" to "Beleži poteze", "hr" to "Bilježi geste", "sr" to "Beleži pokrete", "bs" to "Bilježi pokrete", "mk" to "Снимај гестови", "ru" to "Записывать жесты", "uk" to "Записувати жести", "bg" to "Записвай жестовете", "be" to "Запісваць жэсты", "sr-Cyrl" to "Бележи покрете"),
        "pop_body" to mapOf("ms" to "Kogdy je vključeno, slova, ktore potvrdiš pri pisanju — svajpom, izborom iz pasa, dokončenjem znanogo slova — sut lokalno čisljene za spis najpopularnějših medžuslovjanskih slov. Psevdonimno (identifikator telefona niže), bez personalnyh danyh. Ničto se ne posyla avtomatično — do bazy dojde jedino v grupě, ktoru sam pošlješ. Standardno izključeno.", "en" to "When on, Interslavic words you CONFIRM while typing — swipe, picking from the bar, finishing a known word — are counted LOCALLY to feed a ranking of the most popular Interslavic words. Pseudonymously (device id below), no personal data. Nothing leaves automatically — it reaches the database only in a batch you send yourself. Off by default.", "pl" to "Gdy włączone, słowa międzysłowiańskie, które ZATWIERDZASZ przy pisaniu — swipe'em, wyborem z paska, dokończeniem znanego słowa — są liczone LOKALNIE do rankingu najpopularniejszych słów. Pseudonimowo (identyfikator urządzenia niżej), bez danych osobowych. Nic nie wychodzi samo — trafia do bazy tylko w paczce, którą sam wyślesz. Domyślnie wyłączone.", "nb" to "Når dette er på, telles interslaviske ord du BEKREFTER mens du skriver — med sveip, valg fra linjen eller ved å fullføre et kjent ord — LOKALT til en rangering av de mest brukte ordene. Pseudonymt (enhets-ID nedenfor), uten personopplysninger. Ingenting sendes automatisk — det når databasen bare i pakken du selv sender. Av som standard.", "cs" to "Když je zapnuto, mezislovanská slova, která při psaní POTVRDÍŠ — tahem, výběrem z lišty, dokončením známého slova — se LOKÁLNĚ počítají pro žebříček nejoblíbenějších mezislovanských slov. Pseudonymně (ID zařízení níže), bez osobních údajů. Nic neodchází automaticky — do databáze se dostane jen v balíčku, který sám odešleš. Ve výchozím stavu vypnuto.", "sk" to "Keď je zapnuté, medzislovanské slová, ktoré pri písaní POTVRDÍŠ — ťahom, výberom z lišty, dokončením známeho slova — sa LOKÁLNE počítajú pre rebríček najobľúbenejších medzislovanských slov. Pseudonymne (ID zariadenia nižšie), bez osobných údajov. Nič neodchádza automaticky — do databázy sa dostane len v balíku, ktorý sám odošleš. Predvolene vypnuté.", "sl" to "Ko je vklopljeno, se medslovanske besede, ki jih med tipkanjem POTRDIŠ — s potegom, z izbiro iz vrstice, z dokončanjem znane besede — LOKALNO štejejo za lestvico najbolj priljubljenih medslovanskih besed. Psevdonimno (ID naprave spodaj), brez osebnih podatkov. Nič ne odide samodejno — v bazo pride le v paketu, ki ga sam pošlješ. Privzeto izklopljeno.", "hr" to "Kad je uključeno, međuslavenske riječi koje POTVRDIŠ tijekom pisanja — povlačenjem, odabirom s trake, dovršavanjem poznate riječi — LOKALNO se broje za ljestvicu najpopularnijih međuslavenskih riječi. Pseudonimno (ID uređaja ispod), bez osobnih podataka. Ništa ne odlazi automatski — u bazu stiže samo u paketu koji sam pošalješ. Prema zadanim postavkama isključeno.", "sr" to "Kad je uključeno, međuslovenske reči koje POTVRDIŠ dok kucaš — prevlačenjem, izborom sa trake, dovršavanjem poznate reči — broje se LOKALNO za rang-listu najpopularnijih međuslovenskih reči. Pod pseudonimom (identifikator uređaja ispod), bez ličnih podataka. Ništa ne odlazi automatski — podaci stižu u bazu samo u paketu koji sam pošalješ. Podrazumevano isključeno.", "bs" to "Kad je uključeno, međuslavenske riječi koje POTVRDIŠ dok kucaš — prevlačenjem, odabirom s trake, dovršavanjem poznate riječi — broje se LOKALNO za rang-listu najpopularnijih međuslavenskih riječi. Pod pseudonimom (identifikator uređaja ispod), bez ličnih podataka. Ništa ne odlazi automatski — podaci stižu u bazu samo u paketu koji sam pošalješ. Zadano isključeno.", "mk" to "Кога е вклучено, меѓусловенските зборови што ги ПОТВРДУВАШ додека пишуваш — со лизгање, со избор од лентата, со довршување познат збор — се бројат ЛОКАЛНО за рангирање на најпопуларните меѓусловенски зборови. Под псевдоним (идентификатор на уредот подолу), без лични податоци. Ништо не заминува автоматски — податоците стигнуваат во базата само во пакет што сам го испраќаш. Стандардно исклучено.", "ru" to "Если включено, межславянские слова, которые ты ПОДТВЕРЖДАЕШЬ при наборе — свайпом, выбором на панели, дописыванием известного слова, — подсчитываются ЛОКАЛЬНО для рейтинга самых популярных межславянских слов. Псевдонимно (идентификатор устройства ниже), без персональных данных. Ничего не отправляется автоматически — данные попадают в базу только пакетом, который ты сам отправишь. По умолчанию выключено.", "uk" to "Якщо ввімкнено, міжсловʼянські слова, які ти ПІДТВЕРДЖУЄШ під час набору — свайпом, вибором на панелі, дописуванням відомого слова, — підраховуються ЛОКАЛЬНО для рейтингу найпопулярніших міжсловʼянських слів. Псевдонімно (ідентифікатор пристрою нижче), без персональних даних. Нічого не надсилається автоматично — дані потрапляють до бази лише пакетом, який ти сам надішлеш. Типово вимкнено.", "bg" to "Когато е включено, междуславянските думи, които ПОТВЪРЖДАВАШ при писане — с плъзгане, с избор от лентата, с довършване на позната дума, — се броят ЛОКАЛНО за класация на най-популярните междуславянски думи. Псевдонимно (идентификаторът на устройството е по-долу), без лични данни. Нищо не се изпраща автоматично — данните стигат до базата само в пакет, който сам изпратиш. По подразбиране е изключено.", "be" to "Калі ўключана, міжславянскія словы, якія ты ПАЦВЯРДЖАЕШ падчас набору — свайпам, выбарам на панэлі, дапісваннем вядомага слова, — падлічваюцца ЛАКАЛЬНА для рэйтынгу самых папулярных міжславянскіх слоў. Псеўданімна (ідэнтыфікатар прылады ніжэй), без асабістых дадзеных. Нічога не адпраўляецца аўтаматычна — дадзеныя трапляюць у базу толькі пакетам, які ты сам адправіш. Па змаўчанні выключана.", "sr-Cyrl" to "Кад је укључено, међусловенске речи које ПОТВРДИШ док куцаш — превлачењем, избором са траке, довршавањем познате речи — броје се ЛОКАЛНО за ранг-листу најпопуларнијих међусловенских речи. Под псеудонимом (идентификатор уређаја испод), без личних података. Ништа не одлази аутоматски — подаци стижу у базу само у пакету који сам пошаљеш. Подразумевано искључено."),
        "pop_head" to mapOf("ms" to "Poredok popularnosti (opcionalno)", "en" to "Popularity ranking (optional)", "pl" to "Ranking popularności (opcjonalnie)", "nb" to "Popularitetsrangering (valgfritt)", "cs" to "Žebříček oblíbenosti (volitelné)", "sk" to "Rebríček obľúbenosti (voliteľné)", "sl" to "Lestvica priljubljenosti (neobvezno)", "hr" to "Ljestvica popularnosti (neobavezno)", "sr" to "Rang-lista popularnosti (opciono)", "bs" to "Rang-lista popularnosti (opcionalno)", "mk" to "Рангирање по популарност (опционално)", "ru" to "Рейтинг популярности (необязательно)", "uk" to "Рейтинг популярності (необовʼязково)", "bg" to "Класация по популярност (по избор)", "be" to "Рэйтынг папулярнасці (неабавязкова)", "sr-Cyrl" to "Ранг-листа популарности (опционо)"),
